const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const browser=await chromium.launch({args:['--no-sandbox']});try{const p=await browser.newPage({viewport:{width:390,height:844}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{profileStorage.removeItem('deutsch16_course_v2');profileStorage.removeItem(DEUTSCH_REVIEW.key);window.testSpoken='';window.speak=s=>{testSpoken=s}});
 for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});await p.click('[data-course-open]');await p.waitForSelector('#courseLessonView:not(.hidden)');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+5))throw Error('Course overflows '+width);await p.click('[data-course-action="home"]');}
 await p.click('[data-course-open]');if(await p.locator('#courseLessonView [data-speak]').count()!==10)throw Error('Reading examples incomplete');
 await p.evaluate(()=>{for(const row of DEUTSCH_COURSE.reading)for(const de of row.slice(2))if(!recordedAudioFiles(de))throw Error('Reading audio missing '+de);for(const [de,ua]of DEUTSCH_COURSE.phrases)if(!recordedAudioFiles(de)||!DEUTSCH_REVIEW.resolve([de,ua]))throw Error('Phrase audio or stable binding missing '+de)});
 await p.click('[data-course-action="forward"]');if(await p.locator('#courseLessonView .course-card').count()!==8)throw Error('Phrase cards missing');await p.reload();await p.evaluate(()=>{window.testSpoken='';window.speak=s=>{testSpoken=s}});await p.click('[data-course-open]');if(!await p.locator('#courseLessonView').textContent().then(s=>s.includes('Крок 2 із 3')))throw Error('Step not resumed');
 await p.click('[data-course-action="forward"]');await p.click('[data-course-type="listen"]');await p.click('[data-course-type="write"]');await p.click('[data-course-action="forward"]');let counts={reading:0,de:0,listen:0,write:0};let failed=false;
 for(let n=0;n<12;n++){
  const q=p.locator('#courseLessonView .course-question'),txt=await q.innerText();let answer,type;
  if(await p.locator('#courseWrite').count()){type='write';answer=await p.evaluate(txt=>DEUTSCH_COURSE.phrases.find(p=>txt.includes(p[1]))[0],txt);await p.locator('#courseWrite').fill(answer.replace('ü','ue'));await p.locator('#courseWriteForm button').click();}
  else{const data=await p.evaluate(txt=>DEUTSCH_COURSE.readingTasks.find(t=>txt.includes(t.prompt)),txt);if(data){type='reading';answer=data.answer}else if(await p.locator('[data-course-listen]').count()){type='listen';await p.click('[data-course-listen]');answer=await p.evaluate(()=>DEUTSCH_COURSE.phrases.find(p=>p[0]===testSpoken)[1]);if(txt.includes(await p.evaluate(()=>testSpoken)))throw Error('Listening reveals German answer');}else{type='de';answer=await p.evaluate(txt=>DEUTSCH_COURSE.phrases.find(p=>txt.includes(p[0]))[1],txt)}
   let options=p.locator('[data-course-answer]');if(!failed&&type!=='reading'){const wrong=options.filter({hasText:/.+/});let vals=await options.allTextContents();await p.locator('[data-course-answer]').nth(vals.findIndex(x=>x!==answer)).click();failed=true;}else await p.locator('[data-course-answer]').filter({hasText:answer}).click();
  }
  counts[type]++;if(!await p.locator('[data-course-action="next"]').isVisible())throw Error('Cannot advance');await p.click('[data-course-action="next"]');
 }
 if(counts.reading!==4||Math.max(counts.de,counts.listen,counts.write)-Math.min(counts.de,counts.listen,counts.write)>1)throw Error('Practice not balanced '+JSON.stringify(counts));
 if(!await p.evaluate(()=>DEUTSCH_COURSE.state().completed&&DEUTSCH_COURSE.state().lastScore===92))throw Error('Completion score invalid');const cards=await p.evaluate(()=>Object.values(DEUTSCH_REVIEW.snapshot().data.cards));if(cards.length!==8||cards.filter(c=>c.bad===1).length!==1)throw Error('First attempt scheduling invalid');
 await p.reload();await p.waitForSelector('#newCourseStart');if(!await p.locator('#newCourseStart').innerText().then(s=>s.includes('Пройдено')))throw Error('Completion not persisted');
 await p.click('#profileButton');await p.fill('#profileAddInput','Новий учень');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);if(await p.evaluate(()=>DEUTSCH_COURSE.state().completed||DEUTSCH_REVIEW.snapshot().known.size))throw Error('Course leaked between profiles');
 await p.click('[data-course-open]');await p.click('#wordsTab');if(!await p.locator('#courseLessonView').evaluate(el=>el.classList.contains('hidden')))throw Error('Course navigation leaked');if(errors.length)throw Error(errors.join('; '));console.log('PASS first lesson: reading/8 phrases, recorded audio, resume, balanced selectable modes, first-attempt SRS, completion and isolated profiles, 320–1280px');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
